import Fastify from 'fastify'
import { lstat, readdir } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join, resolve } from 'node:path'

export type Source = 'Pi' | 'Claude'
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }

/** Source folders in traversal order. Roots are implicit and never returned as entries. */
export const sources: ReadonlyArray<{ name: Source; folder: string }> = [
  { name: 'Pi', folder: 'pi' },
  { name: 'Claude', folder: 'claude' },
]

const defaultFixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))

/**
 * The fixture root is resolved from this module, not the shell's working directory.
 * MD_MANAGER_FIXTURE_ROOT overrides it for local experiments; the supplied folder
 * must contain pi/ and claude/ subdirectories. No request can change it.
 */
export const fixtureRoot = process.env.MD_MANAGER_FIXTURE_ROOT
  ? resolve(process.env.MD_MANAGER_FIXTURE_ROOT)
  : defaultFixtureRoot

const byName = (a: { name: string }, b: { name: string }) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)

/**
 * Lists every eligible directory and Markdown file under both sources as one flat,
 * deterministically ordered list: Pi before Claude, then a pre-order walk with
 * siblings in code-unit order. Only names are read; contents are never opened.
 * Symlinks (files, directories, or a source root itself) are never followed.
 */
export async function listEntries(root = fixtureRoot): Promise<Entry[]> {
  const entries: Entry[] = []
  async function walk(directory: string, source: Source, prefix = '') {
    const children = await readdir(directory, { withFileTypes: true })
    children.sort(byName)
    for (const child of children) {
      // Dirent never reports a symlink as a directory or file, so links are skipped here.
      const path = prefix ? `${prefix}/${child.name}` : child.name
      if (child.isDirectory()) {
        entries.push({ source, path, kind: 'directory' })
        await walk(join(directory, child.name), source, path)
      } else if (child.isFile() && child.name.toLowerCase().endsWith('.md')) {
        entries.push({ source, path, kind: 'file' })
      }
    }
  }
  for (const { name, folder } of sources) {
    const sourceRoot = join(root, folder)
    const stats = await lstat(sourceRoot)
    if (!stats.isDirectory()) throw new Error(`${folder} source is not a regular directory`)
    await walk(sourceRoot, name)
  }
  return entries
}

export function createApp(root = fixtureRoot) {
  const app = Fastify({ logger: true })
  app.get('/api/entries', async (_request, reply) => {
    try {
      return { entries: await listEntries(root) }
    } catch (error) {
      app.log.error(error, 'Fixture discovery failed')
      return reply.code(500).send({
        error: 'Unable to discover folders and Markdown files. Check that the pi and claude fixture folders exist, are readable, and are not symlinks.',
      })
    }
  })
  return app
}
