export type Source = 'Pi' | 'Claude'
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }

export const sourceNames: readonly Source[] = ['Pi', 'Claude']

export const sourceInfo: Record<Source, { glyph: string; description: string }> = {
  Pi: { glyph: 'π', description: 'Skills and workflow notes for the Pi agent.' },
  Claude: { glyph: 'C', description: 'Subagents and workflow notes for Claude.' },
}

export function isSource(value: string): value is Source {
  return (sourceNames as readonly string[]).includes(value)
}

/** Where the URL points: the home page, a folder inside a source, or nothing we know. */
export type Location =
  | { kind: 'home' }
  | { kind: 'folder'; source: Source; segments: string[] }
  | { kind: 'unknown' }

/** Parses a pathname such as `/Pi/skills/my%20folder` into a location. Each segment is decoded independently. */
export function parseLocation(pathname: string): Location {
  let segments: string[]
  try {
    segments = pathname.split('/').filter(Boolean).map(decodeURIComponent)
  } catch {
    return { kind: 'unknown' }
  }
  if (segments.length === 0) return { kind: 'home' }
  const [source, ...rest] = segments
  if (!isSource(source)) return { kind: 'unknown' }
  return { kind: 'folder', source, segments: rest }
}

/** Builds the URL for a folder, encoding each segment so spaces, `#`, `?` and `%` survive. */
export function folderHref(source: Source, segments: readonly string[] = []): string {
  return '/' + [source, ...segments].map(encodeURIComponent).join('/')
}

/** The immediate children of one folder, each already sorted alphabetically. */
export type FolderListing = { folders: string[]; documents: string[] }

export type EntryIndex = Map<string, FolderListing>

export function folderKey(source: Source, segments: readonly string[]): string {
  return `${source}/${segments.join('/')}`
}

const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })
const alphabetical = (a: string, b: string) => collator.compare(a, b) || (a < b ? -1 : a > b ? 1 : 0)

/**
 * Turns the flat entries list into a map from folder key to its immediate children.
 * Source roots always exist; every directory entry gets its own (possibly empty) listing.
 */
export function buildIndex(entries: readonly Entry[]): EntryIndex {
  const index: EntryIndex = new Map()
  const listingFor = (key: string) => {
    let listing = index.get(key)
    if (!listing) {
      listing = { folders: [], documents: [] }
      index.set(key, listing)
    }
    return listing
  }
  for (const source of sourceNames) listingFor(folderKey(source, []))
  for (const entry of entries) {
    const slash = entry.path.lastIndexOf('/')
    const parentPath = slash === -1 ? '' : entry.path.slice(0, slash)
    const name = entry.path.slice(slash + 1)
    const parent = listingFor(`${entry.source}/${parentPath}`)
    if (entry.kind === 'directory') {
      parent.folders.push(name)
      listingFor(`${entry.source}/${entry.path}`)
    } else {
      parent.documents.push(name)
    }
  }
  for (const listing of index.values()) {
    listing.folders.sort(alphabetical)
    listing.documents.sort(alphabetical)
  }
  return index
}
