import { useSyncExternalStore } from 'react'

/**
 * Minimal History API router. Folder navigation pushes real URLs, and scroll
 * positions are remembered per history entry so Back/Forward restore the prior
 * listing position while entering a folder always starts at the top.
 */

type HistoryState = { key?: string } | null

const STORAGE_KEY = 'md-manager:scroll-positions'
const listeners = new Set<() => void>()
const positions = new Map<string, number>()

function loadPositions() {
  try {
    const stored = JSON.parse(sessionStorage.getItem(STORAGE_KEY) ?? '{}') as Record<string, number>
    for (const [key, value] of Object.entries(stored)) positions.set(key, value)
  } catch { /* storage unavailable: positions only live for this page */ }
}

function persistPositions() {
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(Object.fromEntries(positions)))
  } catch { /* ignore */ }
}

function newKey() {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
}

function currentKey(): string {
  const state = window.history.state as HistoryState
  if (state?.key) return state.key
  const key = newKey()
  window.history.replaceState({ ...(state ?? {}), key }, '')
  return key
}

let installed = false
function install() {
  if (installed || typeof window === 'undefined') return
  installed = true
  if ('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual'
  loadPositions()
  currentKey()
  window.addEventListener('scroll', () => positions.set(currentKey(), window.scrollY), { passive: true })
  window.addEventListener('pagehide', persistPositions)
  window.addEventListener('popstate', () => listeners.forEach(listener => listener()))
}

function subscribe(listener: () => void) {
  install()
  listeners.add(listener)
  return () => { listeners.delete(listener) }
}

const getPathname = () => window.location.pathname

/** The current pathname, updated on navigation and browser history traversal. */
export function useLocationPath(): string {
  return useSyncExternalStore(subscribe, getPathname)
}

/** Pushes a new history entry and notifies subscribers. */
export function navigate(href: string) {
  install()
  if (href === window.location.pathname + window.location.search + window.location.hash) return
  positions.set(currentKey(), window.scrollY)
  window.history.pushState({ key: newKey() }, '', href)
  listeners.forEach(listener => listener())
}

/** The scroll position remembered for the current history entry, or 0 for a new one. */
export function rememberedScroll(): number {
  install()
  return positions.get(currentKey()) ?? 0
}

/** True while the viewport matches the media query; re-renders when that changes. */
export function useMediaQuery(query: string): boolean {
  return useSyncExternalStore(
    listener => {
      const media = window.matchMedia(query)
      media.addEventListener('change', listener)
      return () => media.removeEventListener('change', listener)
    },
    () => window.matchMedia(query).matches,
  )
}
