import { useEffect, useRef, useState } from 'react'
import { folderHref, type Source } from '../lib/entries.ts'
import { useMediaQuery } from '../lib/router.ts'
import { Link } from './Link.tsx'

type Crumb = { label: string; href: string }

type BreadcrumbsProps = { source?: Source; segments?: readonly string[] }

/**
 * Home / Source / folder … trail. On narrow screens, intermediate crumbs collapse
 * behind an expansion button; the last crumb is always visible and marked current.
 */
export function Breadcrumbs({ source, segments = [] }: BreadcrumbsProps) {
  const crumbs: Crumb[] = [{ label: 'Home', href: '/' }]
  if (source) {
    crumbs.push({ label: source, href: folderHref(source) })
    segments.forEach((segment, i) => crumbs.push({ label: segment, href: folderHref(source, segments.slice(0, i + 1)) }))
  }
  const narrow = useMediaQuery('(max-width: 640px)')
  const [expanded, setExpanded] = useState(false)
  const firstHiddenRef = useRef<HTMLAnchorElement>(null)
  const collapsed = narrow && !expanded && crumbs.length > 3

  useEffect(() => {
    if (expanded) firstHiddenRef.current?.focus()
  }, [expanded])

  const lastIndex = crumbs.length - 1
  const renderCrumb = (crumb: Crumb, index: number, focusRef?: typeof firstHiddenRef) => (
    <li key={crumb.href}>
      <Link href={crumb.href} ref={focusRef} aria-current={index === lastIndex ? 'page' : undefined}>{crumb.label}</Link>
    </li>
  )

  return (
    <nav aria-label="Breadcrumb" className="breadcrumbs">
      <ol>
        {collapsed
          ? <>
              {renderCrumb(crumbs[0], 0)}
              <li>
                <button
                  type="button"
                  className="breadcrumb-expand"
                  aria-expanded={false}
                  aria-label={`Show ${crumbs.length - 2} hidden folders in the path`}
                  onClick={() => setExpanded(true)}
                >…</button>
              </li>
              {renderCrumb(crumbs[lastIndex], lastIndex)}
            </>
          : crumbs.map((crumb, index) => renderCrumb(crumb, index, index === 1 && expanded ? firstHiddenRef : undefined))}
      </ol>
    </nav>
  )
}
