  const [pending, setPending] = useState(true)
  const [failure, setFailure] = useState<Failure>(null)
  const [announcement, setAnnouncement] = useState('Loading folders and documents…')
  const controllerRef = useRef<AbortController | null>(null)

  const load = useCallback(async (mode: 'initial' | 'refresh') => {
    controllerRef.current?.abort()
    const controller = new AbortController()
    controllerRef.current = controller
    setPending(true)
    setAnnouncement(mode === 'refresh' ? 'Refreshing folders and documents…' : 'Loading folders and documents…')
    try {
      const response = await fetch('/api/entries', { signal: controller.signal })
      if (!response.ok) throw new Error(`Discovery failed with HTTP ${response.status}`)
      const data = await response.json() as { entries: Entry[] }
      if (controller.signal.aborted) return
      setListing({ entries: data.entries, index: buildIndex(data.entries) })
      setFailure(null)
      setAnnouncement(mode === 'refresh' ? 'Folders and documents refreshed.' : 'Folders and documents loaded.')
    } catch {
      if (controller.signal.aborted) return
      setFailure(mode)
      setAnnouncement(mode === 'refresh' ? 'Refresh failed. Showing the previous contents.' : 'Loading failed.')
    } finally {
      if (!controller.signal.aborted) setPending(false)
    }
  }, [])

  useEffect(() => {
    void load('initial')
    return () => controllerRef.current?.abort()
  }, [load])

  // Entering a folder starts at the top; history traversal restores the remembered position.
  const ready = listing !== null || (!pending && failure === 'initial')
  useLayoutEffect(() => {
    if (ready) window.scrollTo(0, rememberedScroll())
  }, [pathname, ready])

  useEffect(() => {
    document.title = location.kind === 'folder'
      ? `${[...location.segments].reverse().concat(location.source).join(' · ')} · MD Manager`
      : 'MD Manager'
  }, [location])

  const refresh = () => { void load(listing ? 'refresh' : 'initial') }

  let body
  if (location.kind === 'home') {
    body = <SourceCards />
  } else if (location.kind === 'unknown') {
    body = (
      <section className="notice" aria-labelledby="notice-heading">
        <h2 id="notice-heading">Page not found</h2>
        <p>Only the Pi and Claude sources can be browsed.</p>
        <p><Link href="/">Go to Home</Link></p>
      </section>
    )
  } else if (!listing) {
    body = failure === 'initial' && !pending
      ? null
      : <FolderViewPlaceholder />
  } else {
    const { source, segments } = location
    const folder = listing.index.get(folderKey(source, segments))
    body = folder
      ? <FolderView key={pathname} source={source} segments={segments} listing={folder} />
      : (
        <section className="notice" aria-labelledby="notice-heading">
          <h2 id="notice-heading">Folder not found</h2>
          <p>
            <strong>{[source, ...segments].join(' / ')}</strong> is not in the current listing.
            It may have been renamed or deleted, or the link may be out of date.
          </p>
          <p><Link href={folderHref(source)}>Go to the {source} root</Link> or <Link href="/">Home</Link>.</p>
        </section>
      )
  }

  return (
    <>
      <header className="app-header">
        <h1>MD Manager</h1>
        <p className="tagline">Read-only browser for the Pi and Claude Markdown fixtures.</p>
      </header>
      <main>
        <div className="toolbar">
          <Breadcrumbs key={pathname} source={location.kind === 'folder' ? location.source : undefined} segments={location.kind === 'folder' ? location.segments : []} />
          <button type="button" className="refresh" onClick={refresh} disabled={pending} aria-busy={pending || undefined}>
            <span className="refresh-icon" aria-hidden="true">↻</span> Refresh
          </button>
        </div>
        <p role="status" className="live-status">{announcement}</p>
        {failure === 'initial' && !pending && (
          <div role="alert" className="error">
            <p>{initialError}</p>
            <button type="button" onClick={refresh}>Retry</button>
          </div>
        )}
        {failure === 'refresh' && listing && (
          <div role="alert" className="error">
            <p>{refreshError}</p>
          </div>
        )}
        {body}
      </main>
    </>
  )
}

export default App
