import { useEffect, useRef, useState } from 'react'
import { folderHref, type Source } from '../lib/entries.ts'
import { useMediaQuery } from '../lib/router.ts'
import { Link } from './Link.tsx'

type Crumb = { label: string; href: string; current: boolean }

type BreadcrumbsProps = { source?: Source; segments?: readonly string[] }

/**
 * Home / Source / folder … trail. On narrow screens, intermediate crumbs collapse
 * behind an expansion button; the last crumb is always visible and marked current.
 */
export function Breadcrumbs({ source, segments = [] }: BreadcrumbsProps) {
  const crumbs: Crumb[] = [{ label: 'Home', href: '/', current: false }]
  if (source) {
    crumbs.push({ label: source, href: folderHref(source), current: false })
    segments.forEach((segment, i) => crumbs.push({ label: segment, href: folderHref(source, segments.slice(0, i + 1)), current: false }))
  }
  crumbs[crumbs.length - 1].current = true

  const narrow = useMediaQuery('(max-width: 640px)')
  const [expanded, setExpanded] = useState(false)
  const listRef = useRef<HTMLOListElement>(null)
  const collapsed = narrow && !expanded && crumbs.length > 3

  // After expanding, move focus to the first crumb that was hidden so keyboard users are not stranded.
  useEffect(() => {
    if (expanded) listRef.current?.querySelector<HTMLAnchorElement>('li:nth-child(2) a')?.focus()
  }, [expanded])

  const visible = collapsed ? [crumbs[0], null, crumbs[crumbs.length - 1]] : crumbs

  return (
    <nav aria-label="Breadcrumb" className="breadcrumbs">
      <ol ref={listRef}>
        {visible.map(crumb => crumb === null
          ? (
            <li key="expand">
              <button
                type="button"
                className="breadcrumb-expand"
                aria-expanded={false}
                aria-label={`Show ${crumbs.length - 2} hidden folders in the path`}
                onClick={() => setExpanded(true)}
              >…</button>
            </li>
          )
          : (
            <li key={crumb.href}>
              <Link href={crumb.href} aria-current={crumb.current ? 'page' : undefined}>{crumb.label}</Link>
            </li>
          ))}
      </ol>
    </nav>
  )
}
