input.command:
git rm -q tests/listing.spec.ts && cat > tests/helpers.ts <<'EOF'
import { test as base, expect, type Page } from '@playwright/test'
import { randomBytes } from 'node:crypto'
import { mkdir, rm, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

export const repoRoot = fileURLToPath(new URL('..', import.meta.url))
export const fixturesDir = join(repoRoot, 'fixtures')
export const apiUrl = `http://127.0.0.1:${process.env.MD_MANAGER_API_PORT ?? '3001'}`

export type Source = 'Pi' | 'Claude'
const sourceFolder: Record<Source, string> = { Pi: 'pi', Claude: 'claude' }

/** A unique, recognisable name so leaked artifacts are easy to spot and never collide. */
export function uniqueName(label = 'scratch') {
  return `zz-test-${label}-${Date.now().toString(36)}-${randomBytes(3).toString('hex')}`
}

const created: string[] = []

/** Scratch files and folders inside the committed fixture tree. Everything created here is removed by `cleanupScratch`. */
export const scratch = {
  dir(source: Source, ...segments: string[]) {
    return join(fixturesDir, sourceFolder[source], ...segments)
  },
  /** Creates a folder under a source (or under an existing scratch folder) and registers it for removal. */
  async mkdir(source: Source, ...segments: string[]) {
    const path = this.dir(source, ...segments)
    await mkdir(path, { recursive: true })
    created.push(this.dir(source, segments[0]))
    return path
  },
  /** Creates a file under a source and registers its top-level scratch ancestor for removal. */
  async file(source: Source, ...segments: string[]) {
    const path = this.dir(source, ...segments)
    await mkdir(join(path, '..'), { recursive: true })
    await writeFile(path, '')
    created.push(this.dir(source, segments[0]))
    return path
  },
  async remove(source: Source, ...segments: string[]) {
    await rm(this.dir(source, ...segments), { recursive: true, force: true })
  },
}

/** Register with `test.afterEach` in every spec that mutates fixtures. Runs even when the test failed. */
export async function cleanupScratch() {
  const paths = created.splice(0)
  await Promise.all(paths.map(path => rm(path, { recursive: true, force: true })))
}

export function folderUrl(source: Source, ...segments: string[]) {
  return '/' + [source, ...segments].map(encodeURIComponent).join('/')
}

export async function waitForListing(page: Page) {
  await expect(page.getByRole('status')).toHaveText(/loaded|refreshed/)
}

export const test = base
export { expect }
EOF
cat > tests/browse.spec.ts <<'EOF'
import { test, expect, scratch, cleanupScratch, folderUrl, waitForListing, apiUrl } from './helpers.ts'

test.afterEach(cleanupScratch)

test('home shows Pi and Claude source cards as links and no file table', async ({ page, request }) => {
  await expect.poll(async () => (await request.get(`${apiUrl}/api/entries`)).status()).toBe(200)
  await page.goto('/')
  await waitForListing(page)
  const sources = page.getByRole('region', { name: 'Sources' })
  const pi = sources.getByRole('link', { name: /^Pi\b/ })
  const claude = sources.getByRole('link', { name: /^Claude\b/ })
  await expect(pi).toHaveAttribute('href', '/Pi')
  await expect(claude).toHaveAttribute('href', '/Claude')
  await expect(pi).toContainText('Skills and workflow notes')
  await expect(page.getByRole('navigation', { name: 'Breadcrumb' }).getByRole('link', { name: 'Home' })).toHaveAttribute('aria-current', 'page')
  await expect(page.getByRole('table')).toHaveCount(0)
})

test('a source root separates folders from documents, counts immediate children, and hides non-Markdown files', async ({ page }) => {
  await page.goto('/')
  await waitForListing(page)
  await page.getByRole('link', { name: /^Pi\b/ }).click()
  await expect(page).toHaveURL('/Pi')

  const folders = page.getByRole('region', { name: 'Folders · 1' })
  const documents = page.getByRole('region', { name: 'Documents · 1' })
  await expect(folders.getByRole('link')).toHaveText(['skills'])
  await expect(folders.getByRole('link', { name: 'skills' })).toHaveAttribute('href', '/Pi/skills')
  await expect(documents.getByRole('listitem')).toHaveText(['MDworkflow.md'])
  await expect(page.getByText('notes.txt')).toHaveCount(0)
  // Nested files are not immediate children.
  await expect(page.getByText('review.md')).toHaveCount(0)

  // Document cards are static: no links, buttons, or focusable elements inside.
  await expect(documents.locator('a, button, [tabindex]')).toHaveCount(0)
  // Folders precede documents in the DOM.
  await expect(page.locator('main section').nth(0)).toHaveAttribute('aria-labelledby', 'folders-heading')
  await expect(page.locator('main section').nth(1)).toHaveAttribute('aria-labelledby', 'documents-heading')
})

test('Claude root lists its folder and both documents alphabetically', async ({ page }) => {
  await page.goto('/Claude')
  await waitForListing(page)
  await expect(page.getByRole('region', { name: 'Folders · 1' }).getByRole('link')).toHaveText(['subagents'])
  await expect(page.getByRole('region', { name: 'Documents · 2' }).locator('.document-name')).toHaveText(['empty.md', 'workflow.md'])
})

test('folder tiles and breadcrumbs navigate both sources; duplicate filenames stay distinguishable', async ({ page }) => {
  await page.goto('/Pi')
  await waitForListing(page)
  await page.getByRole('link', { name: 'skills' }).click()
  await expect(page).toHaveURL('/Pi/skills')
  const crumbs = page.getByRole('navigation', { name: 'Breadcrumb' })
  await expect(crumbs.getByRole('link')).toHaveText(['Home', 'Pi', 'skills'])
  await expect(crumbs.getByRole('link', { name: 'skills' })).toHaveAttribute('aria-current', 'page')
  await expect(crumbs.getByRole('link', { name: 'Pi' })).not.toHaveAttribute('aria-current', 'page')
  await expect(page.getByText('No subfolders.')).toBeVisible()
  await expect(page.locator('.document-name')).toHaveText(['review.md'])

  // Breadcrumbs go back up, and home reaches the other source.
  await crumbs.getByRole('link', { name: 'Home' }).click()
  await page.getByRole('link', { name: /^Claude\b/ }).click()
  await page.getByRole('link', { name: 'subagents' }).click()
  await expect(page).toHaveURL('/Claude/subagents')
  await expect(page.locator('.document-name')).toHaveText(['implementer.md'])

  // workflow.md exists in both sources; the breadcrumb and URL make each one unambiguous.
  await page.goto('/Pi')
  await expect(page.locator('.document-name')).toHaveText(['workflow.md'])
  await expect(crumbs.getByRole('link', { name: 'Pi' })).toHaveAttribute('aria-current', 'page')
  await page.goto('/Claude')
  await expect(page.locator('.document-name')).toContainText(['workflow.md'])
  await expect(crumbs.getByRole('link', { name: 'Claude' })).toHaveAttribute('aria-current', 'page')
})

test('each section is alphabetical regardless of case, and only .md files become documents', async ({ page }) => {
  const folder = scratch.uniqueOrThrow?.() ?? `zz-test-sort-${Date.now().toString(36)}`
  await scratch.mkdir('Pi', folder, 'b-folder')
  await scratch.mkdir('Pi', folder, 'A-folder')
  await scratch.mkdir('Pi', folder, 'c folder')
  await scratch.file('Pi', folder, 'Zeta.md')
  await scratch.file('Pi', folder, 'alpha.MD')
  await scratch.file('Pi', folder, 'notes.txt')
  await scratch.file('Pi', folder, 'readme.markdown')
  await page.goto(folderUrl('Pi', folder))
  await waitForListing(page)
  await expect(page.getByRole('region', { name: 'Folders · 3' }).getByRole('link')).toHaveText(['A-folder', 'b-folder', 'c folder'])
  await expect(page.getByRole('region', { name: 'Documents · 2' }).locator('.document-name')).toHaveText(['alpha.MD', 'Zeta.md'])
  await expect(page.getByText('notes.txt')).toHaveCount(0)
  await expect(page.getByText('readme.markdown')).toHaveCount(0)
})
EOF
sed -i "s/const folder = scratch.uniqueOrThrow?.() ?? \`zz-test-sort-\${Date.now().toString(36)}\`/const folder = uniqueName('sort')/" tests/browse.spec.ts
sed -i "s/import { test, expect, scratch, cleanupScratch, folderUrl, waitForListing, apiUrl } from '.\/helpers.ts'/import { test, expect, scratch, cleanupScratch, folderUrl, uniqueName, waitForListing, apiUrl } from '.\/helpers.ts'/" tests/browse.spec.ts
grep -n "uniqueName" tests/browse.spec.ts

